 result=dict(run_verified=verified,complete_original_imu=run['delivery']['/lidar_imu'],complete_original_cloud=run['delivery']['/lidar_points'],post=s['post_count'],keyframes=b['keyframes'],committed_loops=len(loops),global_map_points=b['global_map_points'],fixed_extrinsic_verified=s['fixed_translation_max_error_m']<1e-12 and s['fixed_rotation_max_error_deg']<1e-10,absolute_elevation_accuracy='UNKNOWN',real_time_dds_hardware_navigation='NOT_RUN',summary=s,loops=loops)
